@Override
protected boolean tryReleaseHeldRidingAbility(String abilityName) {
    DragonAbility<?> active;
    if (ModAbilities.STEGONAUT_GROUND_EATING.getName().equals(abilityName) && (active = this.combatManager.getActiveAbility()) != null && active.getAbilityType() == ModAbilities.STEGONAUT_GROUND_EATING) {
        ((StegonautGroundEatingAbility)active).requestRelease();
        return true;
    }
    if (ModAbilities.STEGONAUT_GROUND_SLAM.getName().equals(abilityName) && (active = this.combatManager.getActiveAbility()) != null && active.getAbilityType() == ModAbilities.STEGONAUT_GROUND_SLAM) {
