    DragonAbility<?> active;
    if (action == DragonRiderAction.ABILITY_USE && ModAbilities.STEGONAUT_GROUND_SLAM.getName().equals(abilityName) && (active = this.combatManager.getActiveAbility()) != null && active.getAbilityType() == ModAbilities.STEGONAUT_GROUND_SLAM) {
        ((StegonautGroundSlamAbility)active).requestChain();
        return true;
    }
    if (action == DragonRiderAction.ABILITY_STOP && ModAbilities.STEGONAUT_GROUND_SLAM.getName().equals(abilityName) && this.tryReleaseHeldRidingAbility(abilityName)) {
        return true;
    }
    if (action == DragonRiderAction.ABILITY_STOP && ModAbilities.STEGONAUT_GROUND_EATING.getName().equals(abilityName) && this.tryReleaseHeldRidingAbility(abilityName)) {
        return true;
    }
    return super.handleCustomRiderAction(player, action, abilityName, locked);
}

@Override
protected void onRiderOpenInventory(Player player) {
    if (player instanceof ServerPlayer) {
        ServerPlayer serverPlayer = (ServerPlayer)player;
        this.openStegonautInventory(serverPlayer);
    }
}

